begin;
create extension if not exists pgtap with schema extensions;grant usage on schema extensions to cuevo_api;set local search_path=extensions,pg_catalog;select no_plan();
create temporary table sibling_sources(numeric_id uuid,rubric_id uuid);grant select,insert,update on sibling_sources to cuevo_api;
insert into app.parent_relationships(school_id,parent_actor_id,student_actor_id,relationship_type)values('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000072','20000000-0000-4000-8000-000000000018','guardian')on conflict(school_id,parent_actor_id,student_actor_id)do update set status='active',effective_to=null;
insert into app.courses(school_id,id,class_id,subject_id,created_by,title,description,status)values('10000000-0000-4000-8000-000000000001','99200000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Sibling exact enrollment fixture','Synthetic','PUBLISHED');
insert into app.assessments(school_id,id,course_id,created_by,title,instructions,max_score,academic_reference_id)select'10000000-0000-4000-8000-000000000001',('99210000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'99200000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Sibling source '||i,'School authored',10,'61000000-0000-4000-8000-000000000001'from generate_series(1,2)i;
set local role cuevo_api;select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
do $$declare rubric uuid;submission uuid;begin
 rubric:=internal.create_rubric('99200000-0000-4000-8000-000000000001','Sibling rubric','school-sibling-1','[{"key":"explanation","title":"Explanation","levels":[{"key":"shown","label":"Shown","description":"Explain the school example."}]}]');perform internal.configure_assessment_rubric('99210000-0000-4000-8000-000000000002',rubric,1);
 perform set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);submission:=internal.create_learning_submission('99210000-0000-4000-8000-000000000001','Sibling numeric source');perform set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);insert into sibling_sources(numeric_id)values(internal.release_marking(internal.mark_submission(submission,0,'Released native zero',1,0,true),1,true));
 perform set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);submission:=internal.create_learning_submission('99210000-0000-4000-8000-000000000002','Sibling rubric source');perform set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);update sibling_sources set rubric_id=internal.release_rubric_marking(internal.mark_rubric_submission(submission,rubric,'[{"criterionKey":"explanation","levelKey":"shown"}]','Human released criterion',2,0,true),1,true);
end$$;
create function pg_temp.parent_contains(target uuid)returns boolean language plpgsql as $$declare page jsonb;cursor_id uuid;begin loop page:=internal.list_parent_current_results(100,cursor_id);if exists(select 1 from jsonb_array_elements(page->'items')item where item->>'id'=target::text)then return true;end if;cursor_id:=(page->>'nextCursor')::uuid;exit when cursor_id is null;end loop;return false;end$$;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);
select ok(pg_temp.parent_contains((select numeric_id from sibling_sources))and pg_temp.parent_contains((select rubric_id from sibling_sources)),'current exact child enrollment permits both native source models');
reset role;
update app.enrollments set status='revoked'where school_id='10000000-0000-4000-8000-000000000001'and class_id='30000000-0000-4000-8000-000000000001'and student_actor_id='20000000-0000-4000-8000-000000000012';
set local role cuevo_api;
select is("authorization".can_read_course('10000000-0000-4000-8000-000000000001','99200000-0000-4000-8000-000000000001'),true,'enrolled sibling still authorizes the course itself');
select ok(not pg_temp.parent_contains((select numeric_id from sibling_sources)),'sibling course enrollment cannot authorize withdrawn child numeric result');
select ok(not pg_temp.parent_contains((select rubric_id from sibling_sources)),'sibling course enrollment cannot authorize withdrawn child rubric result');
select ok(not exists(select 1 from jsonb_array_elements(internal.list_current_native_results_scoped(100,null,'20000000-0000-4000-8000-000000000012')->'items')item where item->>'id'in(select numeric_id::text from sibling_sources union all select rubric_id::text from sibling_sources)),'selected withdrawn child report stays consistent with current parent page');
select ok(exists(select 1 from app.academic_evidence where result_id=(select numeric_id from sibling_sources))and exists(select 1 from app.rubric_evidence where result_id=(select rubric_id from sibling_sources)),'retained historical approved evidence authority is unchanged');
reset role;select*from finish();rollback;
